{
  "cadence_days": [
    1,
    3,
    7
  ],
  "stop_on_reply": true,
  "max_followup_attempts": 3,
  "business_hours_only": true
}

/**
 * Script de descoberta de skills (apenas leitura de metadados)
 * NOTA DE SEGURANÇA: Execução automática desabilitada. Tratado apenas como referência estruturada.
 */
export interface SkillSearchResult {
  slug: string;
  relevanceScore: number;
  tags: string[];
}

{
  "curated_registries": [
    {
      "name": "Firstsys Skills Library",
      "url": "https://firstend.firstsys.com.br/skills"
    },
    {
      "name": "Vercel AI SDK Catalog",
      "url": "https://sdk.vercel.ai"
    }
  ]
}

{
  "max_handoff_turns": 5,
  "enable_consensus_voting": false,
  "timeout_seconds_per_agent": 30
}

{
  "enforce_strict_types": true,
  "max_function_lines": 60,
  "require_unit_tests": true,
  "prohibit_full_file_rewrites": true
}

/**
 * Quality Gate Linter Rules
 * Exemplo de especificação de regras estáticas de engenharia Firstsys.
 */
export const QUALITY_STANDARDS = {
  zeroAnyTypes: true,
  explicitReturnType: true,
  noDeadCode: true
};

{
  "local_storage_path": "./storage/local-first",
  "encryption_cipher": "aes-256-gcm",
  "allow_cloud_fallback": false
}

{
  "target_fps": 12,
  "aesthetic": "handcrafted_paper_collage",
  "required_elements": [
    "visible_fibers",
    "layered_depth_shadows",
    "stop_motion_jitter"
  ],
  "prohibit_digital_smoothness": true
}

{
  "categories": [
    {
      "category_name": "Prova Social",
      "templates": [
        "Review Carousel",
        "Customer Quote Overlay",
        "Star Rating Spotlight",
        "Influencer Badge"
      ]
    },
    {
      "category_name": "Benefício Direto",
      "templates": [
        "Split Problem/Solution",
        "Ingredient Breakdown",
        "3-Step Result",
        "Stat Callout"
      ]
    },
    {
      "category_name": "Autoridade e Comparação",
      "templates": [
        "Us vs Them Grid",
        "Awards Banner",
        "Scientific Backing Chart",
        "Founders Note"
      ]
    }
  ]
}

{
  "required_sheet_angles": 6,
  "require_hex_clothing_anchors": true,
  "video_camera_damping": 0.7,
  "prohibit_random_clothing_changes": true
}

{
  "color_palette": {
    "cream_paper": "#F4F0EA",
    "vox_yellow": "#FFDE00",
    "editorial_black": "#1A1A1A",
    "alert_red": "#E63946"
  },
  "narrative_structure": [
    "Anomaly Hook",
    "Context Collapse",
    "Data Investigation",
    "The Reveal",
    "Broader Implications"
  ],
  "camera_moves": [
    "satellite 3d tilt",
    "whip pan to document",
    "macro lens on newspaper fiber"
  ]
}

{
  "modes": [
    "recreate",
    "recompose"
  ],
  "ambient_light_bleed_integration": true,
  "depth_of_field": "cinematic shallow bokeh f/2.8",
  "prohibit_floating_objects": true
}

{
  "formats": {
    "claymation": {
      "fps": 12,
      "style": "plasticine with thumbprints"
    },
    "paper_animation": {
      "fps": 12,
      "style": "mechanical paper automaton"
    },
    "song_style_ad": {
      "bpm": 120,
      "rhyme_scheme": "AABB"
    },
    "talking_object": {
      "tone": "witty_sarcastic",
      "face_style": "stylized expressive mouth"
    },
    "skeleton_ads": {
      "comedy_style": "situational_relatable_humor"
    }
  }
}

{
  "require_strict_mode": true,
  "max_string_length_default": 1000,
  "prohibit_prototype_keys": [
    "__proto__",
    "constructor",
    "prototype"
  ]
}

{
  "enforce_force_rls": true,
  "tenant_setting_key": "app.current_org_id",
  "require_tenant_id_in_all_primary_tables": true
}
